const PATTERNS = [{"id":"doji","kind":"candle","bias":"neutral","file":"doji.svg","name":{"en":"Doji","hi":"डोजी"},"what":{"en":"Open and close are equal or nearly equal, so the body is a thin line. Buyers and sellers are balanced.","hi":"ओपन और क्लोज़ बराबर या लगभग बराबर, इसलिए बॉडी पतली रेखा जैसी। ख़रीदार और विक्रेता बराबरी पर हैं।"},"where":{"en":"At the end of a strong trend, as a sign of a possible pause.","hi":"मज़बूत ट्रेंड के अंत में, संभावित विराम के संकेत के रूप में।"},"confirm":{"en":"The next candle moves in a new direction with volume.","hi":"अगली कैंडल नई दिशा में वॉल्यूम के साथ चले।"},"mistake":{"en":"Treating every doji as a reversal. In a quiet market they are common and mean little.","hi":"हर डोजी को पलटाव मानना; शांत बाज़ार में ये आम हैं और कुछ नहीं बताते।"}},{"id":"marubozu","kind":"candle","bias":"bullish","file":"marubozu.svg","name":{"en":"Marubozu","hi":"मार्बोज़ू"},"what":{"en":"A full body with no wicks. For a bullish one, the open was the low and the close was the high. Buyers controlled the whole session.","hi":"बिना विक की पूरी बॉडी: तेज़ी वाली में ओपन ही लो और क्लोज़ ही हाई। सत्र पर ख़रीदारों का पूरा नियंत्रण।"},"where":{"en":"As a breakout candle or at the start of a trend, with high volume.","hi":"ब्रेकआउट कैंडल के रूप में या ट्रेंड की शुरुआत में, ज़्यादा वॉल्यूम के साथ।"},"confirm":{"en":"Follow-through: the next candles keep rising.","hi":"आगे की कैंडल भी ऊपर जाएँ।"},"mistake":{"en":"Chasing a large marubozu after the move has already extended.","hi":"बड़ी मार्बोज़ू के बाद चाल पहले ही बढ़ चुकी हो तो पीछा करना।"}},{"id":"bullish-engulfing","kind":"candle","bias":"bullish","file":"bullish-engulfing.svg","name":{"en":"Bullish engulfing","hi":"बुलिश एंगल्फ़िंग"},"what":{"en":"A green candle whose body fully covers the previous red candle's body. Buyers overpowered sellers in one session.","hi":"हरी कैंडल जिसकी बॉडी पिछली लाल कैंडल की बॉडी को पूरी तरह ढक ले। एक सत्र में ख़रीदारों ने विक्रेताओं को हरा दिया।"},"where":{"en":"After a downtrend, at support.","hi":"गिरावट के बाद, सपोर्ट पर।"},"confirm":{"en":"The next candle holds above the engulfing candle's low.","hi":"अगली कैंडल इंगल्फ़िंग कैंडल के लो से ऊपर रहे।"},"mistake":{"en":"Treating a small engulfing candle as strong after a large red one. It is weaker than it looks.","hi":"छोटी इंगल्फ़िंग कैंडल को बड़ी लाल कैंडल के बाद भी उतना ही मज़बूत मानना।"}}];
const INDICATORS = [{"id":"moving-averages","file":"moving-averages.svg","category":"trend","name":{"en":"Moving averages (SMA and EMA)","hi":"मूविंग एवरेज (SMA और EMA)"},"what":{"en":"The average price over a set number of periods. SMA treats every period equally; EMA gives more weight to recent prices, so it reacts faster.","hi":"एक तय अवधि की औसत कीमत। SMA हर अवधि को बराबर वज़न देता है; EMA हाल की कीमतों को ज़्यादा वज़न देता है, इसलिए वह तेज़ी से प्रतिक्रिया देता है।"},"settings":{"en":"20 (short-term), 50 (medium), 200 (long-term) periods are common.","hi":"20 (अल्पकालिक), 50 (मध्यम), 200 (दीर्घकालिक) अवधि आम हैं।"},"when":{"en":"To judge trend direction. Use it in trending markets. In sideways markets it produces many false crossovers.","hi":"ट्रेंड की दिशा समझने के लिए। ट्रेंडिंग बाज़ार में उपयोग करें। साइडवे बाज़ार में यह कई झूठे क्रॉसओवर देता है।"},"how":{"en":"Swing trade: buy when price closes above the 20 EMA in an uptrend (50 SMA above 200 SMA). Put the stop below the 20 EMA or the last swing low. Exit when price closes below the 20 EMA. A 50 SMA crossing above the 200 SMA is a 'golden cross'; the reverse is a 'death cross'.","hi":"स्विंग ट्रेड: अपट्रेंड में जब कीमत 20 EMA के ऊपर बंद हो (50 SMA, 200 SMA के ऊपर) तब ख़रीदें। स्टॉप 20 EMA के नीचे या पिछले स्विंग लो के नीचे रखें। कीमत 20 EMA के नीचे बंद हो तो बाहर निकलें। 50 SMA का 200 SMA को ऊपर पार करना 'गोल्डन क्रॉस' है; उल्टा 'डेथ क्रॉस'।"},"mistake":{"en":"Buying every crossover in a sideways range. Also, a longer average lags more, so a 200-period average turns late.","hi":"साइडवे रेंज में हर क्रॉसओवर पर ख़रीदना। लंबा एवरेज ज़्यादा देर से चलता है, इसलिए 200 अवधि का एवरेज देर से पलटता है।"},"pairs":{"en":"ADX (is the trend strong?), volume (is the move supported?).","hi":"ADX (ट्रेंड मज़बूत है?), वॉल्यूम (चाल का समर्थन है?)।"}},{"id":"volume","file":"volume.svg","category":"volume","name":{"en":"Volume","hi":"वॉल्यूम"},"what":{"en":"The number of shares traded in a period. It shows how much participation supports a price move.","hi":"किसी अवधि में ट्रेड हुए शेयरों की संख्या। यह बताता है कि कीमत की चाल को कितनी भागीदारी का समर्थन है।"},"settings":{"en":"Compare with a 20-period average volume.","hi":"20-अवधि के औसत वॉल्यूम से तुलना करें।"},"when":{"en":"To confirm breakouts, reversals and trend moves. Always check it alongside any price signal.","hi":"ब्रेकआउट, पलटाव और ट्रेंड चालों की पुष्टि के लिए। हर कीमत संकेत के साथ इसे जाँचें।"},"how":{"en":"Breakout: buy only if volume is at least 1.5 times its 20-day average on the breakout candle. A rally on falling volume is weak; expect a pullback. Very high volume at the end of a long fall (a climax) can mark exhaustion, but confirm with the next candles.","hi":"ब्रेकआउट: ख़रीदें केवल तब जब ब्रेकआउट कैंडल पर वॉल्यूम 20-दिन के औसत का कम से कम 1.5 गुना हो। घटते वॉल्यूम पर तेज़ी कमज़ोर है; पुलबैक की उम्मीद करें। लंबी गिरावट के अंत में बहुत ज़्यादा वॉल्यूम (क्लाइमैक्स) थकान का संकेत हो सकता है, पर अगली कैंडल से पुष्टि करें।"},"mistake":{"en":"Ignoring volume on a breakout and buying a move that has no buyers behind it.","hi":"ब्रेकआउट पर वॉल्यूम को अनदेखा करना और ऐसी चाल ख़रीदना जिसके पीछे ख़रीदार न हों।"},"pairs":{"en":"Any breakout or pattern (for confirmation), and OBV (for the trend of volume).","hi":"कोई भी ब्रेकआउट या पैटर्न (पुष्टि के लिए), और OBV (वॉल्यूम के ट्रेंड के लिए)।"}}];
const GLOSSARY_TERMS = [{"cat":"basics","term":{"en":"Volume","hi":"वॉल्यूम"},"def":{"en":"The number of shares traded in a period. High volume means more participation.","hi":"किसी अवधि में ट्रेड हुए शेयरों की संख्या। ज़्यादा वॉल्यूम का मतलब ज़्यादा भागीदारी।"}},{"cat":"technical","term":{"en":"Trend","hi":"ट्रेंड"},"def":{"en":"The general direction of price: up (higher highs and lows), down (lower highs and lows), or sideways.","hi":"कीमत की सामान्य दिशा: ऊपर (ऊँचे हाई और लो), नीचे (नीचे हाई और लो), या साइडवे।"}},{"cat":"technical","term":{"en":"Support","hi":"सपोर्ट"},"def":{"en":"A price level where buying has tended to appear and stop further falls.","hi":"वह कीमत स्तर जहाँ ख़रीदारी दिखी है और आगे गिरावट रुकी है।"}},{"cat":"technical","term":{"en":"Resistance","hi":"रेज़िस्टेंस"},"def":{"en":"A price level where selling has tended to appear and stop further rises.","hi":"वह कीमत स्तर जहाँ बिकवाली दिखी है और आगे बढ़त रुकी है।"}},{"cat":"technical","term":{"en":"Candlestick","hi":"कैंडलस्टिक"},"def":{"en":"A chart element showing open, high, low and close for a period, coloured by direction.","hi":"किसी अवधि का ओपन, हाई, लो और क्लोज़ दिखाने वाला चार्ट तत्व, दिशा के अनुसार रंगीन।"}}];
window.MP_PRACTICE = {"reading-charts":[["chart","Open a stock's chart on the daily timeframe and switch between candles, OHLC bars, line and Heikin Ashi. Note what each one hides or shows.","किसी शेयर का डेली चार्ट खोलें और कैंडल, OHLC बार, लाइन और हाइकिन आशी में बदलें। देखें कि हर एक क्या दिखाता या छिपाता है।"],["chart","Switch between 5-minute, 1-hour and daily candles for the same stock and describe the trend on each timeframe.","उसी शेयर के 5-मिनट, 1-घंटे और डेली कैंडल देखें और हर टाइमफ़्रेम पर ट्रेंड बताएँ।"],["chart","Use the horizontal-line tool to mark one support and one resistance level, then check where volume was highest.","हॉरिज़ॉन्टल-लाइन टूल से एक सपोर्ट और एक रेज़िस्टेंस स्तर चिह्नित करें, फिर देखें कि वॉल्यूम सबसे ज़्यादा कहाँ था।"]]};
